## Próximo passo: Formulários Interativos

Vou te mostrar como criar um formulário que responde ao usuário usando **useState**:

```jsx
// App.jsx
import { useState } from 'react';

function App() {
  const [nome, setNome] = useState('');
  const [email, setEmail] = useState('');
  const [mensagem, setMensagem] = useState('');

  function handleSubmit(e) {
    e.preventDefault(); // Evita recarregar a página
    alert(`Obrigado, ${nome}! \nEmail: ${email}\nMensagem: ${mensagem}`);
  }

  return (
    <div style={styles.container}>
      <h1 style={styles.titulo}>Fale Conosco</h1>

      <form onSubmit={handleSubmit} style={styles.form}>
        <div style={styles.campo}>
          <label style={styles.label}>Nome:</label>
          <input
            type="text"
            value={nome}
            onChange={(e) => setNome(e.target.value)}
            style={styles.input}
            placeholder="Seu nome"
          />
        </div>

        <div style={styles.campo}>
          <label style={styles.label}>Email:</label>
          <input
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            style={styles.input}
            placeholder="seu@email.com"
          />
        </div>

        <div style={styles.campo}>
          <label style={styles.label}>Mensagem:</label>
          <textarea
            value={mensagem}
            onChange={(e) => setMensagem(e.target.value)}
            style={styles.textarea}
            placeholder="Sua mensagem..."
          />
        </div>

        <button type="submit" style={styles.botao}>
          Enviar
        </button>
      </form>
    </div>
  );
}

const styles = {
  container: {
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    padding: '40px',
    backgroundColor: '#f5f5f5',
    minHeight: '100vh',
    fontFamily: 'Arial, sans-serif',
  },
  titulo: {
    color: '#333',
    marginBottom: '30px',
  },
  form: {
    backgroundColor: 'white',
    padding: '30px',
    borderRadius: '10px',
    boxShadow: '0 4px 10px rgba(0,0,0,0.1)',
    width: '100%',
    maxWidth: '400px',
  },
  campo: {
    marginBottom: '15px',
  },
  label: {
    display: 'block',
    marginBottom: '5px',
    color: '#555',
    fontWeight: 'bold',
  },
  input: {
    width: '100%',
    padding: '10px',
    borderRadius: '5px',
    border: '1px solid #ddd',
    fontSize: '14px',
    boxSizing: 'border-box',
  },
  textarea: {
    width: '100%',
    padding: '10px',
    borderRadius: '5px',
    border: '1px solid #ddd',
    fontSize: '14px',
    minHeight: '100px',
    resize: 'vertical',
    boxSizing: 'border-box',
  },
  botao: {
    width: '100%',
    padding: '12px',
    backgroundColor: '#007bff',
    color: 'white',
    border: 'none',
    borderRadius: '5px',
    fontSize: '16px',
    cursor: 'pointer',
    marginTop: '10px',
  },
};

export default App;
```

## O que aprendemos:

| Conceito | Para que serve |
|----------|----------------|
| `useState` | Guarda dados que mudam |
| `value={valor}` | Input controlado |
| `onChange` | Detecta quando usuário digita |
| `e.preventDefault()` | Impede recarregar a página |

---

## Próximo passo do roadmap:

**CSS Modules** ou **Styled Components** - formas mais organizadas de estilizar seus componentes (em vez de objetos grandes como usei acima).

